    if (!(g.line_count == 93)) __t27_assert_fail("\n  assertion failed:\n    g.line_count = {any}\n", .{ g.line_count });
    if (!(g.node_count == 14)) __t27_assert_fail("\n  assertion failed:\n    g.node_count = {any}\n", .{ g.node_count });
    if (!(g.edge_count == 9)) __t27_assert_fail("\n  assertion failed:\n    g.edge_count = {any}\n", .{ g.edge_count });
    if (!(std.mem.eql(u8, g.node_name[0], "tutorial-08-modules"))) __t27_assert_fail("\n  assertion failed:\n    g.node_name[0] = {any}\n", .{ g.node_name[0] });
    if (!((g.line_start[0] == 1) and (g.line_end[0] == 93))) __t27_assert_fail("\n  assertion failed:\n    g.line_start[0] = {any}\n    g.line_end[0] = {any}\n", .{ g.line_start[0], g.line_end[0] });
    if (!(count_node_kind(g, NODE_USE) == 1)) __t27_assert_fail("\n  assertion failed:\n    count_node_kind(g, NODE_USE) = {any}\n", .{ count_node_kind(g, NODE_USE) });
    if (!(count_node_kind(g, NODE_CONST) == 5)) __t27_assert_fail("\n  assertion failed:\n    count_node_kind(g, NODE_CONST) = {any}\n", .{ count_node_kind(g, NODE_CONST) });
    if (!(count_node_kind(g, NODE_FN) == 3)) __t27_assert_fail("\n  assertion failed:\n    count_node_kind(g, NODE_FN) = {any}\n", .{ count_node_kind(g, NODE_FN) });
    if (!(count_node_kind(g, NODE_TEST) == 3)) __t27_assert_fail("\n  assertion failed:\n    count_node_kind(g, NODE_TEST) = {any}\n", .{ count_node_kind(g, NODE_TEST) });
    if (!(count_node_kind(g, NODE_INVARIANT) == 1)) __t27_assert_fail("\n  assertion failed:\n    count_node_kind(g, NODE_INVARIANT) = {any}\n", .{ count_node_kind(g, NODE_INVARIANT) });
