pub fn validate_edge(g: SpecGraph, j: u32) u8 {
    const k: usize = @as(usize, @intCast(j));
    const ek: u8 = g.edge_kind[k];
    if (valid_edge_kind(ek) == false) {
        return ERR_EDGE_KIND;
    }
    const f: u32 = @as(u32, @intCast(g.edge_from[k]));
    const t: u32 = @as(u32, @intCast(g.edge_to[k]));
    if ((f >= g.node_count) or (t >= g.node_count)) {
        return ERR_EDGE_DANGLING;
    }
    const fk: u8 = g.node_kind[@as(usize, @intCast(f))];
    const tk: u8 = g.node_kind[@as(usize, @intCast(t))];
    if ((EDGE_FROM_KINDS[@as(usize, @intCast(ek))] & kind_bit(fk)) == 0) {
        return ERR_EDGE_ENDPOINT_KIND;
    }
    if ((EDGE_TO_KINDS[@as(usize, @intCast(ek))] & kind_bit(tk)) == 0) {
        return ERR_EDGE_ENDPOINT_KIND;
    }
    const fl: u8 = g.node_label[@as(usize, @intCast(f))];
    const tl: u8 = g.node_label[@as(usize, @intCast(t))];
    if ((fl == LABEL_UNKNOWN) or (tl == LABEL_UNKNOWN)) {
        return ERR_EDGE_UNKNOWN_NODE;
    }
    const el: u8 = g.edge_label[k];
    if (el >= LABEL_UNKNOWN) {
        return ERR_EDGE_LABEL;
    }
    if ((el < fl) or (el < tl)) {
        return ERR_EDGE_LABEL;
    }
    const line: u32 = g.edge_line[k];
    if (line == NO_LINE) {
        if (el != LABEL_DERIVED) {
            return ERR_EDGE_LINE;
        }
    } else if ((span_holds(g, f, line) == false) and (span_holds(g, t, line) == false)) {
        return ERR_EDGE_LINE;
    }
    var i: u32 = 0;
    _ = &i;
    while (i < j) {
        const m: usize = @as(usize, @intCast(i));
        if (((g.edge_kind[m] == ek) and (g.edge_from[m] == g.edge_from[k])) and (g.edge_to[m] == g.edge_to[k])) {
            return ERR_DUPLICATE_EDGE;
        }
        i = i + 1;
    }
    return GRAPH_OK;
}
pub fn validate_graph(g: SpecGraph) u8 {
    const h: u8 = validate_graph_header(g);
    if (h != GRAPH_OK) {
        return h;
    }
    var n: u32 = 0;
    _ = &n;
    while (n < g.node_count) {
        const v: u8 = validate_node(g, n);
        if (v != GRAPH_OK) {
            return v;
        }
        n = n + 1;
    }
    var j: u32 = 0;
    _ = &j;
    while (j < g.edge_count) {
        const w: u8 = validate_edge(g, j);
        if (w != GRAPH_OK) {
            return w;
        }
        j = j + 1;
    }
    return GRAPH_OK;
}
pub fn validate_graph_header(g: SpecGraph) u8 {
    if (g.ir_version != GRAPH_IR_VERSION) {
        return ERR_GRAPH_VERSION;
    }
    if ((std.mem.eql(u8, g.spec_path, "")) or (g.line_count == 0)) {
        return ERR_SPEC_PATH;
    }
    if (g.node_count > MAX_NODES) {
        return ERR_TOO_MANY_NODES;
    }
    if (g.edge_count > MAX_EDGES) {
        return ERR_TOO_MANY_EDGES;
    }
    if (g.node_count == 0) {
        return ERR_MODULE;
    }
    if (g.node_kind[0] != NODE_MODULE) {
        return ERR_MODULE;
    }
    if ((g.line_start[0] != 1) or (g.line_end[0] != g.line_count)) {
        return ERR_MODULE;
    }
    return GRAPH_OK;
}
pub fn validate_node(g: SpecGraph, n: u32) u8 {
    const k: usize = @as(usize, @intCast(n));
    if (valid_node_kind(g.node_kind[k]) == false) {
        return ERR_NODE_KIND;
    }
    if (valid_label(g.node_label[k]) == false) {
